#!/usr/bin/env node
// Builds dist/network_install.sql (one transaction, for the Supabase SQL editor or Lovable chat),
// dist/network_uninstall.sql, and dist/migrations/<ts>_network_install.sql (for the host's supabase/migrations).
// The host mapping is taken from supabase/host_mapping.sql, which the integrator edits first.
import { readFileSync, writeFileSync, mkdirSync, readdirSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const root = join(dirname(fileURLToPath(import.meta.url)), "..");
const mig = join(root, "supabase", "migrations");
const files = readdirSync(mig).filter((f) => /_network_.*\.sql$/.test(f)).sort();
const core = files.filter((f) => f.includes("_core"));
const rest = files.filter((f) => !f.includes("_core"));
const mapping = process.env.NET_HOST_MAPPING ?? join(root, "supabase", "host_mapping.sql");

const part = (label, path) => `\n-- ===== ${label}\n${readFileSync(path, "utf8").trim()}\n`;
const body =
  core.map((f) => part(`supabase/migrations/${f}`, join(mig, f))).join("") +
  part("supabase/host_mapping.sql (integrator-edited)", mapping) +
  rest.map((f) => part(`supabase/migrations/${f}`, join(mig, f))).join("");

const header = (what) =>
  `-- pan-iim-network ${what}. Generated by tools/build-sql-bundle.mjs. Do not edit; edit the sources.\n` +
  `-- Additive only: creates net_* objects in schema public. Idempotent. Remove with dist/network_uninstall.sql.\n`;

mkdirSync(join(root, "dist", "migrations"), { recursive: true });
const install = header("install bundle") + "\nbegin;\n" + body + "\ncommit;\n";
writeFileSync(join(root, "dist", "network_install.sql"), install);
writeFileSync(join(root, "dist", "migrations", "20261114000100_network_install.sql"), header("migration") + body);
writeFileSync(join(root, "dist", "network_uninstall.sql"), readFileSync(join(root, "supabase", "uninstall.sql")));
const sha = createHash("sha256").update(install).digest("hex");
console.log(`dist/network_install.sql  ${install.length} bytes  sha256 ${sha}`);
console.log(`sources: ${[...core, "host_mapping.sql", ...rest].join(", ")}`);
